/** @param {NS} ns */
export async function main(ns) {
  let lvl = ns.getHackingLevel();
  let q = ['home'], s = new Set(q);
  while(q.length) {
    let h = q.pop();
    for(let n of ns.scan(h)) {
      if(!s.has(n)) { s.add(n); q.push(n); }
    }
  }
  let r = [];
  for(let h of s) {
    if(h === 'home') continue;
    let req = ns.getServerRequiredHackingLevel(h);
    let ports = ns.getServerNumPortsRequired(h);
    if(!ns.hasRootAccess(h) && req <= lvl && ports === 0) ns.nuke(h);
    r.push({host:h, req, ports, max:ns.getServerMaxMoney(h), curr:ns.getServerMoneyAvailable(h), root:ns.hasRootAccess(h), sec:ns.getServerSecurityLevel(h), minSec:ns.getServerMinSecurityLevel(h)});
  }
  ns.tprint(JSON.stringify(r));
}

